import manifest from './manifest.json';
import gameIndex from './game-index.json';

/** Every planned game in the course, whether or not its generator exists yet. */
export const gpFinancePlannedGames = manifest.games;
export const gpFinanceUnits = manifest.units as [string, string][];
/**
 * Metadata for the games that have a generator: the chunk that holds it and its number of stages.
 * Generated by `npm run sync:game-index` (a test fails when it is stale). This module imports no generator.
 */
export const gpFinanceGameIndex: Record<string, { chunk: string; stages: number }> = gameIndex;
/** Only games with a generator are playable and listed in the course. */
export const gpFinanceGames = manifest.games.filter(game => game.id in gameIndex);
